from typing import List

def maxStrength(nums: List[int]) -> int:
    # 因為題目給定的陣列長度非常小 (n <= 13)，
    # 使用位運算 (Bitmask) 來窮舉所有可能的非空子集是最簡單且不會出錯的做法。
    n = len(nums)
    max_strength = float('-inf')

    # 從 1 到 2^n - 1，代表所有非空的子集組合
    for i in range(1, 1 << n):
        current_product = 1
        for j in range(n):
            # 如果第 j 位是 1，表示將 nums[j] 加入目前的乘積中
            if (i >> j) & 1:
                current_product *= nums[j]

        if current_product > max_strength:
            max_strength = current_product

    return int(max_strength)

