from typing import List

def maxStrength(nums: List[int]) -> int:
    """
    Finds the maximum strength of a non-empty group from an array of scores.
    The strength is defined as the product of all elements in the selected group.
    """
    # Separate numbers into three categories based on their sign.
    pos = [x for x in nums if x > 0]
    # Sort negatives by absolute value descending to prioritize larger magnitudes.
    neg = sorted([x for x in nums if x < 0], key=abs, reverse=True)
    zero = [x for x in nums if x == 0]

    # Case 1: There is at least one positive number.
    # The maximum product will be the product of all positives and an even 
    # count of negatives with the largest absolute values (to keep the result positive).
    if pos:
        res = 1
        for x in pos:
            res *= x
        if len(neg) % 2 == 0:
            for x in neg:
                res *= x
        else:
            # Exclude the negative with the smallest magnitude (the last one).
            for i in range(len(neg) - 1):
                res *= neg[i]
        return res

    # Case 2: No positive numbers exist, but at least one zero exists.
    # The maximum product could be 0 or a positive number from an even count of negatives.
    if zero:
        if len(neg) >= 2:
            res = 1
            if len(neg) % 2 == 0:
                for x in neg:
                    res *= x
            else:
                # Exclude the smallest magnitude negative to keep the product positive.
                for i in range(len(neg) - 1):
                    res *= neg[i]
            return max(res, 0)
        else:
            # If there's only one or no negatives, and at least one zero exists,
            # the maximum product is 0.
            return 0

    # Case 3: No positives and no zeros exist (all numbers are negative).
    if len(neg) == 1:
        # Only one negative number available; that's our only choice for a non-empty group.
        return neg[0]
    else:
        # More than one negative number exists. To maximize the product, we want 
        # to take an even count of negatives with the largest absolute values.
        res = 1
        if len(neg) % 2 == 0:
            for x in neg:
                res *= x
        else:
            # Exclude the smallest magnitude negative (last one).
            for i in range(len(neg) - 1):
                res *= neg[i]
        return res

