from typing import List

def countMatchingSubarrays(nums: List[int], pattern: List[int]) -> int:
    n = len(nums)
    m = len(pattern)
    count = 0

    # The subarray size is m + 1.
    # We iterate through all possible starting indices i such that i + m < n.
    for i in range(n - m):
        is_match = True
        for k in range(m):
            left = nums[i + k]
            right = nums[i + k + 1]
            p = pattern[k]

            if p == 1:
                if not (right > left):
                    is_match = False
                    break
            elif p == 0:
                if not (right == left):
                    is_match = False
                    break
            elif p == -1:
                if not (right < left):
                    is_match = False
                    break

        if is_match:
            count += 1

    return count
