def countMatchingSubarrays(nums: list, pattern: list):
    n = len(nums)
    m = len(pattern)
    count = 0
    # The subarray size is m + 1, so the start index i can range from 0 to n - (m + 1).
    # Let's re-verify: if n=6 and m=2, the subarray size is 3.
    # Possible start indices are 0, 1, 2, 3. n-m = 4. range(4) gives exactly these.
    for i in range(n - m):
        match = True
        for k in range(m):
            val_curr = nums[i + k]
            val_next = nums[i + k + 1]
            p = pattern[k]
            if p == 1:
                if not (val_next > val_curr):
                    match = False
                    break
            elif p == 0:
                if not (val_next == val_curr):
                    match = False
                    break
            elif p == -1:
                if not (val_next < val_curr):
                    match = False
                    break
        if match:
            count += 1
    return count

