import itertools

def minimumString(a: str, b: str, c: str) -> str:
    """
    Finds the shortest string containing a, b, and c as substrings.
    If multiple exist, returns the lexicographically smallest one.
    """
    # Step 1: Filter out strings that are already substrings of others.
    # This simplifies the problem because any string containing a larger 
    # string automatically contains its substring.
    strs = [a, b, c]
    to_remove = [False] * 3
    for i in range(3):
        for j in range(3):
            if i != j and strs[i] in strs[j]:
                # To handle identical strings correctly (e.g., "abc", "abc"),
                # we only mark one of them for removal by comparing indices.
                if strs[i] == strs[j]:
                    if i > j:
                        to_remove[i] = True
                        break
                else:
                    to_remove[i] = True
                    break

    remaining = [strs[i] for i in range(3) if not to_remove[i]]

    # Step 2: Try all permutations of the remaining strings.
    # For each permutation, we merge them by maximizing overlaps between adjacent strings.
    best_result = None

    for p in itertools.permutations(remaining):
        current_str = p[0]
        for i in range(1, len(p)):
            next_s = p[i]
            max_overlap = 0
            # Find the maximum overlap where a suffix of 'current_str' matches a prefix of 'next_s'.
            # We check lengths from the largest possible down to 1.
            for ov in range(min(len(current_str), len(next_s)), 0, -1):
                if current_str.endswith(next_s[:ov]):
                    max_overlap = ov
                    break
            # Append only the part of next_s that is not overlapping with current_str.
            current_str += next_s[max_overlap:]

        # Step 3: Update the best result based on length, then lexicographical order.
        if best_result is None:
            best_result = current_str
        else:
            if len(current_str) < len(best_result):
                best_result = current_str
            elif len(current_str) == len(best_result):
                if current_str < best_result:
                    best_result = current_str

    return best_result

